from __future__ import annotations

from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def replace_once(path: str, old: str, new: str) -> None:
    target = ROOT / path
    text = target.read_text(encoding="utf-8")
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"expected exactly one match in {path}, found {count}: {old[:120]!r}")
    target.write_text(text.replace(old, new, 1), encoding="utf-8")


# 1) Exact melee reach uses one coordinate convention everywhere. The existing
# scheduler stopped at weapon reach PLUS two body radii, while actual attack
# geometry and weapon damage both used center-to-center weapon reach. That left
# a deterministic ~600 mm dead zone for ordinary 300 mm body radii.
replace_once(
    "runtime/shinobi_runtime/martial_world/exact_combat.py",
    '''        distance = planar_distance_mm(actor_position, target_position)\n        body_allowance = int(actor_position.get("body_radius_mm", 300)) + int(target_position.get("body_radius_mm", 300))\n        required = max(0, distance - physical_reach_mm(profile) - body_allowance)\n''',
    '''        distance = planar_distance_mm(actor_position, target_position)\n        # ``physical_reach_mm`` is the same center-to-center contact envelope\n        # consumed by exact melee geometry and weapon contact. Do not add body\n        # radii here or the approach stops outside the distance at which the\n        # strike can actually intersect and transmit damage.\n        required = max(0, distance - physical_reach_mm(profile))\n''',
)

